import java.util.Comparator;

final class SortContext implements HeapFactory {

    @Override
    public HeapSorter<Integer> forIntArray(int[] arr) {
        return new RangeHeap(arr);
    }

    @Override
    public <T> HeapSorter<T> forObjectArray(T[] arr, Comparator<T> cmp) {
        return new ObjectRangeHeap<>(arr, cmp);
    }
}
import java.util.Comparator;

public class HeapSort {

    private static final HeapFactory FACTORY = new SortContext();

    public static void heapSort(int[] arr) {
        heapSort(arr, 0, arr.length);
    }

    public static void heapSort(int[] arr, int from, int to) {
        if (from < 0 || to > arr.length || from > to)
            throw new IllegalArgumentException(
                "Invalid range [" + from + ", " + to + ") for array of length " + arr.length);
        FACTORY.forIntArray(arr).sort(from, to);
    }

    public static <T> void heapSort(T[] arr, Comparator<T> cmp) {
        heapSort(arr, 0, arr.length, cmp);
    }

    public static <T> void heapSort(T[] arr, int from, int to, Comparator<T> cmp) {
        if (from < 0 || to > arr.length || from > to)
            throw new IllegalArgumentException(
                "Invalid range [" + from + ", " + to + ") for array of length " + arr.length);
        FACTORY.forObjectArray(arr, cmp).sort(from, to);
    }
}
class RangeHeap extends AbstractHeap implements HeapSorter<Integer> {
    private final int[] arr;
    private int from;

    RangeHeap(int[] arr) {
        this.arr = arr;
    }

    @Override
    public void sort(int from, int to) {
        this.from = from;
        sort(to - from);
    }

    @Override
    protected boolean isGreater(int i, int j) {
        return arr[from + i] > arr[from + j];
    }

    @Override
    protected void swap(int i, int j) {
        int temp = arr[from + i];
        arr[from + i] = arr[from + j];
        arr[from + j] = temp;
    }
}
import java.util.Comparator;

class ObjectRangeHeap<T> extends AbstractHeap implements HeapSorter<T> {
    private final T[] arr;
    private int from;
    private final Comparator<T> cmp;

    ObjectRangeHeap(T[] arr, Comparator<T> cmp) {
        this.arr = arr;
        this.cmp = cmp;
    }

    @Override
    public void sort(int from, int to) {
        this.from = from;
        sort(to - from);
    }

    @Override
    protected boolean isGreater(int i, int j) {
        return cmp.compare(arr[from + i], arr[from + j]) > 0;
    }

    @Override
    protected void swap(int i, int j) {
        T temp = arr[from + i];
        arr[from + i] = arr[from + j];
        arr[from + j] = temp;
    }
}

